// Shared benchmark / test corpus for all packages. Everything comes from the
// workspace's node_modules (real-world code), corpus/ (npm tarballs fetched
// with `npm pack`), Nodepod's pnpm store next to this repo (optional) and
// verify/jsx-corpus (generated by verify/make-jsx-corpus.mjs).

import { readFileSync, readdirSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

export const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const nm = join(root, "node_modules");
// Nodepod checkout next to this repo (optional extra corpus)
export const nodepodStore = join(root, "../Nodepod/node_modules/.pnpm");
export const nodepodSrc = join(root, "../Nodepod/src");
// real-world JSX (verify/make-jsx-corpus.mjs)
export const jsxCorpus = join(root, "verify/jsx-corpus");

export const read = (rel) => readFileSync(join(nm, rel));
export const readText = (rel) => readFileSync(join(nm, rel), "utf8");

// JavaScript sources, small -> huge
export const jsFiles = {
  "zod-errors.js (1.6KB esm)": "zod/v4/classic/errors.js",
  "zod-schemas.js (51KB esm)": "zod/v4/classic/schemas.js",
  "react-dom-client.prod (536KB cjs)": "react-dom/cjs/react-dom-client.production.js",
  "babel-parser (513KB cjs)": "@babel/parser/lib/index.js",
  "rollup node-entry (948KB esm)": "rollup/dist/es/shared/node-entry.js",
  "react-dom-client.dev (1MB cjs)": "react-dom/cjs/react-dom-client.development.js",
  "three.module (1.2MB esm)": "three/build/three.module.js",
  "typescript.js (9MB cjs)": "typescript/lib/typescript.js",
};

export function loadJs(filterBig = false) {
  const out = [];
  for (const [name, rel] of Object.entries(jsFiles)) {
    if (filterBig && name.includes("9MB")) continue;
    try {
      out.push({ name, rel, code: readText(rel), module: /esm/.test(name) });
    } catch {}
  }
  return out;
}

export const tarballs = () =>
  readdirSync(join(root, "corpus"))
    .filter((f) => f.endsWith(".tgz"))
    .map((f) => ({ name: f, bytes: new Uint8Array(readFileSync(join(root, "corpus", f))) }));

// Deterministic pseudo-random bytes (xorshift) — incompressible data
export function randomBytes(n, seed = 12345) {
  const out = new Uint8Array(n);
  let x = seed >>> 0 || 1;
  for (let i = 0; i < n; i++) {
    x ^= x << 13; x >>>= 0;
    x ^= x >>> 17;
    x ^= x << 5; x >>>= 0;
    out[i] = x & 255;
  }
  return out;
}

// Structured JSON-ish text
export function jsonText(targetBytes) {
  const items = [];
  let size = 0, i = 0;
  while (size < targetBytes) {
    const s = JSON.stringify({ id: i, name: `package-${i % 977}`, version: `${i % 13}.${i % 7}.${i % 29}`, deps: { a: "^1.0.0", ["b" + (i % 31)]: "~2.3.4" }, ok: i % 3 === 0, score: (i * 7919) % 10007 / 3 });
    items.push(s);
    size += s.length + 1;
    i++;
  }
  return "[" + items.join(",") + "]";
}

export const utf8 = (s) => new TextEncoder().encode(s);

export function listFiles(dir, exts, out = [], limit = Infinity) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return out; }
  for (const e of entries) {
    if (out.length >= limit) break;
    const p = join(dir, e.name);
    if (e.isDirectory()) listFiles(p, exts, out, limit);
    else if (exts.some((x) => e.name.endsWith(x))) out.push(p);
  }
  return out;
}

export { nm, statSync };
